-- quota_limits (expected 0 mismatches)
WITH entries AS (SELECT user_id,activity_id,biz_type,bucket_type,bucket_key,delta,limit_delta FROM user_quota_ledger_000 UNION ALL SELECT user_id,activity_id,biz_type,bucket_type,bucket_key,delta,limit_delta FROM user_quota_ledger_001 UNION ALL SELECT user_id,activity_id,biz_type,bucket_type,bucket_key,delta,limit_delta FROM user_quota_ledger_002 UNION ALL SELECT user_id,activity_id,biz_type,bucket_type,bucket_key,delta,limit_delta FROM user_quota_ledger_003), changes AS (SELECT user_id,activity_id,SUM(CASE WHEN bucket_type='DAY' THEN limit_delta ELSE 0 END) day_delta,SUM(CASE WHEN bucket_type='MONTH' THEN limit_delta ELSE 0 END) month_delta FROM entries GROUP BY user_id,activity_id) SELECT COUNT(*) FROM raffle_activity_account a LEFT JOIN changes c ON a.user_id=c.user_id AND a.activity_id=c.activity_id WHERE a.day_limit<>a.opening_day_limit+COALESCE(c.day_delta,0) OR a.month_limit<>a.opening_month_limit+COALESCE(c.month_delta,0);

